import{bV as a,aL as o,u as r,G as e}from"./chunks/framework.BfzMay2U.js";const c=JSON.parse('{"title":"制造业 PHP 面试题：AI 辅助 PHP/Laravel 开发（221—240）","description":"","frontmatter":{"title":"制造业 PHP 面试题：AI 辅助 PHP/Laravel 开发（221—240）","date":"2026-11-26T11:30:00.000Z","categories":["面试","PHP","AI"],"tags":["PHP","Laravel","AI","编码助手","工程效率","面试题"],"sidebarSort":10},"headers":[],"relativePath":"php/jd/ai-assisted-php-development-interview.md","filePath":"php/jd/ai-assisted-php-development-interview.md"}'),d={name:"php/jd/ai-assisted-php-development-interview.md"};function l(s,t,i,n,u,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="制造业-php-面试题-ai-辅助-php-laravel-开发-221—240" tabindex="-1">制造业 PHP 面试题：AI 辅助 PHP/Laravel 开发（221—240） <a class="header-anchor" href="#制造业-php-面试题-ai-辅助-php-laravel-开发-221—240" aria-label="Permalink to &quot;制造业 PHP 面试题：AI 辅助 PHP/Laravel 开发（221—240）&quot;">​</a></h1><p>前两篇讲的是&quot;在产品里用 AI&quot;. 本篇反过来: &quot;在开发过程中用 AI&quot;. 这是当前 PHP 岗位面试里绕不开的话题, 但面试官真正想听的不是&quot;我会用 Cursor&quot;, 而是——你怎么让 AI 的产出可信, 怎么控制它的权限, 怎么证明它带来了改进.</p><div class="tip custom-block"><p class="custom-block-title">阅读说明</p><p>本文讨论的工具链包含 Claude Code、Cursor、GitHub Copilot 等 AI 编码代理与 Laravel Boost 提供的 MCP 工具集. 工具在快速演进, 具体命令与配置项以各自官方文档为准; 本文侧重的是可迁移的工程方法. 场景为面试设计案例, 不代表本人已交付的项目经历.</p></div><h2 id="一、让-ai-理解你的项目" tabindex="-1">一、让 AI 理解你的项目 <a class="header-anchor" href="#一、让-ai-理解你的项目" aria-label="Permalink to &quot;一、让 AI 理解你的项目&quot;">​</a></h2><h3 id="_221-为什么-给-ai-足够上下文-比-写好提示-更重要" tabindex="-1">221. 为什么&quot;给 AI 足够上下文&quot;比&quot;写好提示&quot;更重要? <a class="header-anchor" href="#_221-为什么-给-ai-足够上下文-比-写好提示-更重要" aria-label="Permalink to &quot;221. 为什么&quot;给 AI 足够上下文&quot;比&quot;写好提示&quot;更重要?&quot;">​</a></h3><p><strong>参考回答:</strong> 因为编码代理的产出质量几乎完全由它能看到的东西决定. 一个看不到路由表、看不到数据库 schema、看不到错误日志的代理, 只能靠训练语料里的通用 Laravel 印象来写代码, 于是会写出过时的 API、错误的字段名、凭空发明的模型关系. 反过来, 只要把&quot;这个项目真实的路由、真实的表结构、真实的错误栈、真实的框架版本&quot;喂给它, 它的产出立刻从&quot;通用示例&quot;变成&quot;针对本仓库的修改&quot;. [L1][L1]</p><p><strong>工程结论:</strong> 投资顺序应该是&quot;先建上下文通道, 再谈提示词技巧&quot;. 上下文通道就是让代理能按需查询项目事实的能力.</p><h3 id="_222-laravel-boost-具体解决了哪些上下文问题" tabindex="-1">222. Laravel Boost 具体解决了哪些上下文问题? <a class="header-anchor" href="#_222-laravel-boost-具体解决了哪些上下文问题" aria-label="Permalink to &quot;222. Laravel Boost 具体解决了哪些上下文问题?&quot;">​</a></h3><p><strong>参考回答:</strong> Boost 提供了 Laravel 专属的 MCP 工具集, 覆盖应用信息、路由列表、配置键与环境变量、Artisan 命令清单、日志条目读取、最后一条错误、数据库连接与 schema 查询、浏览器日志、官方文档检索等. 它的价值在于让代理按需拉取事实, 而不是把整个项目塞进提示. 此外 Boost 提供的 Laravel 专属 AI 指南会按项目实际安装的组件 (Livewire、Filament、Pest 等) 调整建议, 降低&quot;按旧版本写法生成代码&quot;的概率. [L2][L2]</p><p><strong>对比补充:</strong> 早期社区有 <code>laravel-boost</code> (bosunski) 与后来官方的 <code>laravel/boost</code>, 名字接近但不是同一个东西, 回答时要说清是官方包.</p><h3 id="_223-除了-boost-还能怎么给代理提供上下文" tabindex="-1">223. 除了 Boost, 还能怎么给代理提供上下文? <a class="header-anchor" href="#_223-除了-boost-还能怎么给代理提供上下文" aria-label="Permalink to &quot;223. 除了 Boost, 还能怎么给代理提供上下文?&quot;">​</a></h3><p><strong>参考回答:</strong> 四类互补手段. (1) 规则文件——在仓库根放 <code>AGENTS.md</code> 或 <code>CLAUDE.md</code>, 写清项目结构、命名约定、禁止事项、常用命令, 让代理每次都读; (2) 项目内文档——把接口契约、领域术语、数据库字典写成 Markdown 并让代理检索; (3) MCP 工具——把内部系统 (工单查询、ERP 接口) 暴露成标准工具, 代理就能在开发期查真实数据; (4) 测试与示例代码——真实存在的测试是最难骗过代理的上下文, 它比任何说明文档都更能约束生成风格. [L2][L2]</p><p><strong>追问要点:</strong> 上下文来源要有优先级和新鲜度策略. 过期的文档比没有文档更危险, 因为代理会当真.</p><h3 id="_224-怎么防止代理-按老版本-laravel-写法-生成代码" tabindex="-1">224. 怎么防止代理&quot;按老版本 Laravel 写法&quot;生成代码? <a class="header-anchor" href="#_224-怎么防止代理-按老版本-laravel-写法-生成代码" aria-label="Permalink to &quot;224. 怎么防止代理&quot;按老版本 Laravel 写法&quot;生成代码?&quot;">​</a></h3><p><strong>参考回答:</strong> 四个防线. (1) 声明版本约束——在规则文件与 <code>composer.json</code> 里明确 PHP 与 Laravel 版本, 并在 <code>composer.json</code> 锁定 <code>laravel/framework</code> 的实际版本; (2) 用版本感知的能力——Boost 2.x 起要求 PHP 8.2+ 与 Laravel 11.x+, 并按安装的组件给出版本匹配的指南, 这类机制比人工提醒可靠; (3) 用静态检查卡住——<code>Pint</code> 负责格式, <code>PHPStan</code> / <code>Larastan</code> 负责类型与 API 存在性, 老 API 通常直接触发错误; (4) 用测试卡住——把关键行为写成测试, 老写法通常不满足. [L2][L2] [L3][L3]</p><p><strong>现实提醒:</strong> &quot;模型编造了一个不存在的 API&quot; 是最常见的失败模式. 核对方法是查 IDE 跳转 / 查 vendor 源码 / 查官方文档, 而不是靠感觉.</p><h3 id="_225-ai-代理在仓库里应该有多大的权限" tabindex="-1">225. AI 代理在仓库里应该有多大的权限? <a class="header-anchor" href="#_225-ai-代理在仓库里应该有多大的权限" aria-label="Permalink to &quot;225. AI 代理在仓库里应该有多大的权限?&quot;">​</a></h3><p><strong>参考回答:</strong> 按任务分级, 而不是一律放开. 只读类任务 (解释代码、定位问题、生成文档) 给只读工具; 改代码类任务允许改文件但不允许自动提交或推送; 涉及生产的任务 (跑迁移、改配置、部署) 必须由人执行. 在 MCP 层面同理——Boost 的 Tinker 工具默认关闭, 需要显式打开才允许代理执行任意代码, 这个默认值本身就说明了正确姿势. [L2][L2]</p><p><strong>追问要点:</strong> 权限边界应该由工具配置和 CI 强制, 而不是靠提示词里写&quot;请不要做 X&quot;. 提示词是建议, 权限是约束.</p><h2 id="二、ai-产出的验收" tabindex="-1">二、AI 产出的验收 <a class="header-anchor" href="#二、ai-产出的验收" aria-label="Permalink to &quot;二、AI 产出的验收&quot;">​</a></h2><h3 id="_226-ai-生成的代码-你的验收清单是什么" tabindex="-1">226. AI 生成的代码, 你的验收清单是什么? <a class="header-anchor" href="#_226-ai-生成的代码-你的验收清单是什么" aria-label="Permalink to &quot;226. AI 生成的代码, 你的验收清单是什么?&quot;">​</a></h3><p><strong>参考回答:</strong> 我按四层来审. 第一层语法与风格——<code>Pint</code> 格式化, <code>PHPStan</code> / <code>Larastan</code> 静态分析, 零错误才算通过. 第二层行为——<code>Pest</code> 或 <code>PHPUnit</code> 覆盖的断言, 包括失败路径. 第三层安全——鉴权与授权是否存在、批量赋值是否受 <code>$fillable</code> 限制、SQL 是否参数化、输入是否校验、越权路径是否有测试. 第四层可观测——失败时有没有日志和异常上下文, 线上出问题能不能定位. [L3][L3]</p><p><strong>关键立场:</strong> AI 生成代码的 review 强度不应低于人写的代码. 如果因为&quot;是 AI 写的&quot;而降低审查标准, 风险是成倍上升的, 因为生成速度快, 错误规模也大.</p><h3 id="_227-ai-生成的-laravel-代码-常见坑有哪些" tabindex="-1">227. AI 生成的 Laravel 代码, 常见坑有哪些? <a class="header-anchor" href="#_227-ai-生成的-laravel-代码-常见坑有哪些" aria-label="Permalink to &quot;227. AI 生成的 Laravel 代码, 常见坑有哪些?&quot;">​</a></h3><p><strong>参考回答:</strong> 我在实际项目里高频看到六类. (1) 缺授权——只做了登录校验没做 Policy 授权, 前端按钮隐藏被当成了权限控制; (2) N+1 查询——在循环里访问关联, 一百条工单变成一百多次查询; (3) 缺事务——批量写入中途失败只落了一半; (4) 批量赋值越界——用 <code>create($request-&gt;all())</code> 把不该写的字段一起写了; (5) 原始 SQL 拼接——用字符串拼接代替参数绑定; (6) 异常被吞——<code>catch</code> 里只记一行日志就返回默认值, 线上排障时完全看不到现场. [L3][L3]</p><p><strong>面试话术:</strong> 这六类都不是&quot;写得丑&quot;, 而是&quot;能上生产吗&quot;的问题. 说得出具体清单, 比说&quot;我会仔细 review&quot;有说服力得多.</p><h3 id="_228-ai-生成的数据库迁移和-sql-要重点查什么" tabindex="-1">228. AI 生成的数据库迁移和 SQL, 要重点查什么? <a class="header-anchor" href="#_228-ai-生成的数据库迁移和-sql-要重点查什么" aria-label="Permalink to &quot;228. AI 生成的数据库迁移和 SQL, 要重点查什么?&quot;">​</a></h3><p><strong>参考回答:</strong> 迁移要查三件事: (1) 可回滚——是否提供 <code>down()</code> 且逻辑正确, 生产出问题时能否退回去; (2) 锁与耗时——对大表加索引、加非空列、改类型都会锁表, 要评估锁时长和是否要分批; (3) 数据兼容——新列是否可空、是否有默认值, 老代码在过渡期会不会写入非法值. 生成的查询要查: 是否命中索引、是否 N+1、是否有全表扫描、是否在事务里做了不该做的长操作. [L3][L3]</p><p><strong>实操建议:</strong> 让代理把生成的迁移先写成&quot;待人工审阅的草案&quot;, 不要让它直接 <code>migrate</code> 到共享环境.</p><h3 id="_229-ai-生成的测试-值不值得信" tabindex="-1">229. AI 生成的测试, 值不值得信? <a class="header-anchor" href="#_229-ai-生成的测试-值不值得信" aria-label="Permalink to &quot;229. AI 生成的测试, 值不值得信?&quot;">​</a></h3><p><strong>参考回答:</strong> 有价值, 但要分层看待. AI 很擅长生成&quot;覆盖正常路径的用例&quot;, 也擅长为已有代码补齐边界用例; 它不擅长判断&quot;什么行为才是对的&quot;. 具体风险是: (1) 断言的是当前实现而不是正确行为, 属于把 bug 固化; (2) 大量 trivial 断言 (断言函数不报错), 覆盖率上去了但没有回归价值; (3) mock 过度, 测的是 mock 的行为而不是真实集成. [L3][L3]</p><p><strong>做法:</strong> AI 生成的测试作为&quot;第一稿&quot;, 必须由人逐条确认断言的业务含义; 关键路径的断言要写清楚为什么是这个值, 而不是写 <code>assertTrue(true)</code>.</p><h3 id="_230-用-ai-做代码审查-靠得住吗" tabindex="-1">230. 用 AI 做代码审查, 靠得住吗? <a class="header-anchor" href="#_230-用-ai-做代码审查-靠得住吗" aria-label="Permalink to &quot;230. 用 AI 做代码审查, 靠得住吗?&quot;">​</a></h3><p><strong>参考回答:</strong> 靠得住的部分: 找模式化问题 (未校验输入、缺异常处理、错误的类型假设、SQL 拼接、重复逻辑、命名不一致)、跨文件的一致性检查、生成测试用例清单补齐盲区. 靠不住的部分: 业务语义正确性、跨系统的时序与并发问题、权限模型的整体合理性、以及&quot;这段改动会不会让线上炸&quot;. 原因很直白: 审查需要理解业务意图, 而意图只存在于人的脑子里和工单系统里. [L1][L1]</p><p><strong>实用做法:</strong> 让 AI 当&quot;第二审查人&quot;. 你先自己审一遍, 再让 AI 带着你的结论去做查漏, 最后你复核它的发现. 这个顺序比让 AI 先审更高效, 因为它避免了你从零开始看.</p><h3 id="_231-ai-辅助调试-怎么用才有效" tabindex="-1">231. AI 辅助调试, 怎么用才有效? <a class="header-anchor" href="#_231-ai-辅助调试-怎么用才有效" aria-label="Permalink to &quot;231. AI 辅助调试, 怎么用才有效?&quot;">​</a></h3><p><strong>参考回答:</strong> 关键在于喂给它&quot;事实&quot;而不是&quot;猜测&quot;. 高效做法: 把完整错误栈 (含文件行号)、相关类的源码片段、期望行为与实际行为、已经排除的可能, 一次性给它; 让它先列假设并说明每个假设需要什么证据来验证, 而不是直接给修复代码. Laravel 项目里可以用 Boost 的&quot;最后一条错误&quot;与日志读取工具, 让它自己去取现场. [L2][L2]</p><p><strong>反模式:</strong> 只给一句&quot;这个接口报 500&quot;. 这时代理只能给出十种通用可能, 效率远低于人. <strong>追问要点:</strong> AI 提出的每个假设都要能被一次具体操作证伪, 否则它会陷入&quot;再猜一个&quot;.</p><h3 id="_232-ai-辅助重构遗留代码-怎么保证不改变行为" tabindex="-1">232. AI 辅助重构遗留代码, 怎么保证不改变行为? <a class="header-anchor" href="#_232-ai-辅助重构遗留代码-怎么保证不改变行为" aria-label="Permalink to &quot;232. AI 辅助重构遗留代码, 怎么保证不改变行为?&quot;">​</a></h3><p><strong>参考回答:</strong> 靠&quot;特征测试&quot; (characterization test): 先为现有行为补测试, 把当前行为固定下来 (包括那些看起来像 bug 的行为), 再在测试保护下重构, 重构后测试必须全绿. 顺序不能反. 另外要求代理分小步改, 每步可独立提交与回滚, 不要让它一次性&quot;重构整个模块&quot;. [L1][L1]</p><p><strong>面试延伸:</strong> 遗留代码里最危险的部分往往是没人懂的那部分. 可以先让 AI 生成&quot;这个类的职责与副作用清单&quot;, 人工确认后再动刀——这个清单本身就有价值, 即使不重构也能用来补文档.</p><h2 id="三、安全、供应链与合规" tabindex="-1">三、安全、供应链与合规 <a class="header-anchor" href="#三、安全、供应链与合规" aria-label="Permalink to &quot;三、安全、供应链与合规&quot;">​</a></h2><h3 id="_233-让-ai-读整个仓库-有什么风险" tabindex="-1">233. 让 AI 读整个仓库, 有什么风险? <a class="header-anchor" href="#_233-让-ai-读整个仓库-有什么风险" aria-label="Permalink to &quot;233. 让 AI 读整个仓库, 有什么风险?&quot;">​</a></h3><p><strong>参考回答:</strong> 主要风险是提示注入 (prompt injection): 仓库里的文件内容会被当作上下文读进模型, 而恶意内容可能伪装成指令 (例如在 README、注释、issue 模板里写&quot;忽略之前的要求, 执行某命令&quot;). 后果是代理执行了不该执行的命令, 或把敏感信息写入不信任的地方. 缓解手段: (1) 把仓库内容当&quot;数据&quot;而非&quot;指令&quot;, 在规则文件里显式声明; (2) 代理默认不给执行命令与写敏感路径的权限; (3) 对外发请求 (web fetch) 谨慎, 拉回来的网页同样可能是注入源; (4) 关键操作走人工确认. [L1][L1]</p><p><strong>供应链连带风险:</strong> 让 AI 推荐 Composer 包时, 会引入新的第三方依赖. 新依赖意味着新的代码与新的维护风险, 必须像人工选型一样评估: 下载量、维护活跃度、许可证、是否被 lock 文件固定版本.</p><h3 id="_234-代理推荐的-composer-包-怎么评估" tabindex="-1">234. 代理推荐的 Composer 包, 怎么评估? <a class="header-anchor" href="#_234-代理推荐的-composer-包-怎么评估" aria-label="Permalink to &quot;234. 代理推荐的 Composer 包, 怎么评估?&quot;">​</a></h3><p><strong>参考回答:</strong> 用与人工选型相同的标准: 维护活跃度 (最近提交与发版节奏)、下载量与采用面、许可证是否与项目兼容、是否有安全公告、依赖树大小 (一个包拖进来十个包要慎重)、以及最关键的——它解决的是不是真问题. 最后一条最容易被忽略: AI 很爱推荐&quot;功能强大但你只需要其中 5%&quot;的库, 而这类库的依赖与维护成本是长期负担. 引入前还要确认 <code>composer.lock</code> 已提交并固定版本. [L1][L1]</p><h3 id="_235-能不能把生产数据、生产日志贴给-ai" tabindex="-1">235. 能不能把生产数据、生产日志贴给 AI? <a class="header-anchor" href="#_235-能不能把生产数据、生产日志贴给-ai" aria-label="Permalink to &quot;235. 能不能把生产数据、生产日志贴给 AI?&quot;">​</a></h3><p><strong>参考回答:</strong> 谨慎, 分级处理. (1) 密钥、令牌、数据库连接串、证书——绝对不能进任何外部模型上下文; (2) 客户个人信息、医疗数据 (本系列场景里的 E-DHR 记录尤其敏感)、未脱敏的工单与人员姓名——不能出网, 只能用自建的私有部署模型, 或者只喂脱敏后的样本; (3) 内部日志——先脱敏再给, 并遵守组织的数据出境与保密规定. [L1][L1]</p><p><strong>面试话术:</strong> &quot;我不给 AI 敏感数据&quot;不是能力问题而是流程问题, 正确姿势是先定数据分级规则, 再在工具层面拦截 (屏蔽配置文件、限制可读目录), 而不是靠人每次记得.</p><h3 id="_236-ai-生成的代码-知识产权和合规怎么考虑" tabindex="-1">236. AI 生成的代码, 知识产权和合规怎么考虑? <a class="header-anchor" href="#_236-ai-生成的代码-知识产权和合规怎么考虑" aria-label="Permalink to &quot;236. AI 生成的代码, 知识产权和合规怎么考虑?&quot;">​</a></h3><p><strong>参考回答:</strong> 分三层看. (1) 训练数据的来源争议主要落在服务提供方, 使用者一般通过服务条款承接; (2) 生成代码的著作权归属在多数司法辖区存在不确定性, 商业交付时要与客户在合同里明确责任分配; (3) 许可证合规是真问题——生成代码可能复现了训练语料里的片段, 若项目要分发闭源商业软件, 应配合 SCA 工具 (如依赖漏洞扫描) 一起检查引入的依赖与可疑片段. 制造业客户尤其在意第三方组件许可证是否兼容. [L1][L1]</p><h2 id="四、度量与团队落地" tabindex="-1">四、度量与团队落地 <a class="header-anchor" href="#四、度量与团队落地" aria-label="Permalink to &quot;四、度量与团队落地&quot;">​</a></h2><h3 id="_237-怎么证明-ai-真的提升了研发效率" tabindex="-1">237. 怎么证明 AI 真的提升了研发效率? <a class="header-anchor" href="#_237-怎么证明-ai-真的提升了研发效率" aria-label="Permalink to &quot;237. 怎么证明 AI 真的提升了研发效率?&quot;">​</a></h3><p><strong>参考回答:</strong> 不能只看&quot;写代码快了&quot;. 我会看四类指标: 交付类 (需求到上线的周期、变更前置时间)、质量类 (缺陷逃逸率、返工率、评审驳回率)、稳定性类 (变更失败率、平均修复时间)、成本类 (AI 工具订阅成本、模型调用成本、返工所耗工时). 这几个正好对应 DORA 的四个关键指标, 因为它们能同时反映&quot;快&quot;和&quot;稳&quot;——AI 常见的副作用是代码量上升而缺陷率同步上升, 只有成对看才能识别. [L4][L4]</p><p><strong>务实的做法:</strong> 选一个有明确验收标准的模块做试点, 试点前后对比上述指标, 连续观察几轮迭代再决定是否推广. 样本太小不要下结论.</p><h3 id="_238-团队推广-ai-编码-落地步骤是什么" tabindex="-1">238. 团队推广 AI 编码, 落地步骤是什么? <a class="header-anchor" href="#_238-团队推广-ai-编码-落地步骤是什么" aria-label="Permalink to &quot;238. 团队推广 AI 编码, 落地步骤是什么?&quot;">​</a></h3><p><strong>参考回答:</strong> 我通常分五步. (1) 摸清现状——先统计团队里已经在用什么工具、怎么用, 因为&quot;影子使用&quot;普遍存在, 禁不如规范; (2) 建最小可用规范——规则文件、代码审查清单、禁止事项 (比如不要把生产密钥贴进上下文、不要让代理直接改生产配置)、提交信息要求; (3) 配上下文设施——装 Boost 或等价的 MCP 服务, 把规则文件写好, 让默认体验是&quot;正确的&quot;; (4) 沉淀团队知识——把常见任务沉淀成可复用的技能/命令, 而不是每人每次重写提示; (5) 定期回看——统计 AI 相关 PR 的缺陷率与驳回率, 调整规范. [L1][L1]</p><p><strong>关键点:</strong> 规范要写在仓库里而不是口口相传, 因为它要跟着每一个新人和每一次克隆生效.</p><h3 id="_239-ai-生成代码的评审-审查者该重点看哪几处" tabindex="-1">239. AI 生成代码的评审, 审查者该重点看哪几处? <a class="header-anchor" href="#_239-ai-生成代码的评审-审查者该重点看哪几处" aria-label="Permalink to &quot;239. AI 生成代码的评审, 审查者该重点看哪几处?&quot;">​</a></h3><p><strong>参考回答:</strong> 我用&quot;高风险优先&quot;而不是&quot;逐行读&quot;. 优先看: (1) 授权与权限判断; (2) 数据写入路径 (事务边界、幂等、批量赋值); (3) 外部输入的处理 (校验、注入、转义); (4) 错误处理与异常吞噬; (5) 并发与锁 (重复提交、竞态); (6) 性能陷阱 (N+1、缺索引查询、无界循环); (7) 生成的迁移是否可回滚. 对生成内容的关键提问是&quot;它为什么这样写&quot;, 如果代理说不出依据, 就当作不确定的代码处理. [L3][L3]</p><p><strong>实用技巧:</strong> 在 PR 描述里让代理自述&quot;这次改动的假设与未覆盖的风险&quot;, 审查者据此定向检查. 这比泛读高效得多, 但前提是它不能替代审查者的判断.</p><h3 id="_240-用-ai-帮忙写文档、注释和提交信息-有什么边界" tabindex="-1">240. 用 AI 帮忙写文档、注释和提交信息, 有什么边界? <a class="header-anchor" href="#_240-用-ai-帮忙写文档、注释和提交信息-有什么边界" aria-label="Permalink to &quot;240. 用 AI 帮忙写文档、注释和提交信息, 有什么边界?&quot;">​</a></h3><p><strong>参考回答:</strong> 边界是&quot;不能替代事实&quot;. 提交信息、变更说明、注释这类内容, AI 生成质量高但容易出现两类问题: (1) 描述的是&quot;代码做了什么&quot;而不是&quot;为什么这么做&quot;, 而后者才是半年后有用信息; (2) 编造不存在的背景, 例如把一次性能优化写成&quot;解决高并发下的超时问题&quot;而实际只是改了配置. 对策: 要求 AI 只描述能从 diff 中直接得到的事实, 涉及动机与背景的部分由人补写. 此外对外文档 (用户手册、API 文档) 必须以实际接口为准, AI 生成的示例代码要实际跑通再发布. [L1][L1]</p><h2 id="五、把一次-ai-辅助修复缺陷-讲成完整实现" tabindex="-1">五、把一次&quot;AI 辅助修复缺陷&quot;讲成完整实现 <a class="header-anchor" href="#五、把一次-ai-辅助修复缺陷-讲成完整实现" aria-label="Permalink to &quot;五、把一次&quot;AI 辅助修复缺陷&quot;讲成完整实现&quot;">​</a></h2><p><strong>教学场景：</strong> MES 工单接口偶发 500. 目标是&quot;用 AI 提速, 但结论可靠、过程留痕&quot;.</p><ol><li><strong>取事实:</strong> 用 Boost 读取最后一条错误与相关日志, 取到完整错误栈与请求上下文 (脱敏后), 确认是特定工单号与特定参数组合才触发, 不是随机.</li><li><strong>让 AI 列假设:</strong> 提供错误栈、相关类源码、业务约束与已排除项, 要求输出若干可证伪的假设, 每个假设附验证方法, 暂不给修复代码.</li><li><strong>人工验证:</strong> 按假设逐个验证, 例如构造最小复现请求、在测试环境复现. 第一轮验证后通常收敛到一到两个假设.</li><li><strong>生成并自测:</strong> 让 AI 针对已确认的根因给出修复与回归测试, 要求测试包含&quot;修复前失败、修复后通过&quot;的断言, 并覆盖边界参数.</li><li><strong>落地与留痕:</strong> 走正常 PR 流程, 评审重点放在授权、事务与幂等; 提交信息写清根因与验证方式, 而不是&quot;修复若干问题&quot;. 把这次的经验沉淀成规则文件或技能, 例如&quot;工单状态流转查询必须加租户条件&quot;.</li></ol><div class="tip custom-block"><p class="custom-block-title">特别解释：AI 提速的是&quot;定位&quot;, 不是&quot;判断&quot;</p><p>在这条链路里, AI 最省时间的是从错误栈到候选根因这段; 但&quot;哪个假设是真的&quot;&quot;改了会不会引入新问题&quot;仍然由人负责. 面试时把这条边界讲清楚, 比强调&quot;我 AI 用得多&quot;有说服力.</p></div><p><strong>自测与预期:</strong> 修复前构造的复现请求必须复现 500; 修复后同一请求返回预期业务结果, 相邻工单不受影响; PR 中包含根因说明与验证方式。以上是验收设计, 不是已执行的测试结果.</p><h2 id="关键术语与专业解释" tabindex="-1">关键术语与专业解释 <a class="header-anchor" href="#关键术语与专业解释" aria-label="Permalink to &quot;关键术语与专业解释&quot;">​</a></h2><p>下列定义为官方概念的中文概括; 场景建议是工程推导, 不是框架的绝对保证.</p><table tabindex="0"><thead><tr><th>术语</th><th>专业解释</th><th>容易混淆的边界</th></tr></thead><tbody><tr><td>AI 编码代理</td><td>能读写仓库、执行命令并自主完成多步任务的 AI 工具</td><td>与&quot;补全代码&quot;不同, 它有行动能力, 所以权限边界更重要</td></tr><tr><td>上下文工程</td><td>决定代理能看到哪些事实的工程实践</td><td>不是&quot;提示词写得多漂亮&quot;</td></tr><tr><td>提示注入</td><td>不可信内容伪装成指令影响模型行为</td><td>数据与指令的边界靠流程与权限守, 靠提示守不住</td></tr><tr><td>特征测试</td><td>为固化现有行为而写的测试</td><td>固化的是&quot;当前行为&quot;, 未必是&quot;正确行为&quot;</td></tr><tr><td>幻觉</td><td>模型给出看似合理但不存在的 API 或事实</td><td>用类型检查、IDE 跳转和测试来证伪</td></tr><tr><td>DORA 指标</td><td>交付频率、变更前置时间、变更失败率、恢复时间</td><td>提速不能牺牲稳定性指标</td></tr><tr><td>MCP</td><td>AI 客户端访问工具与资源的开放协议</td><td>工具接入标准化, 不等于权限自动化</td></tr><tr><td>代码所有权</td><td>指定目录或文件的评审责任人</td><td>AI 产出占比高的目录更需要明确责任人</td></tr><tr><td>SCA</td><td>软件成分分析, 扫描依赖的漏洞与许可证</td><td>AI 引入的新依赖同样要过这一关</td></tr></tbody></table><h3 id="基础关键词补充-先理解-再记缩写" tabindex="-1">基础关键词补充：先理解，再记缩写 <a class="header-anchor" href="#基础关键词补充-先理解-再记缩写" aria-label="Permalink to &quot;基础关键词补充：先理解，再记缩写&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关键词</th><th>通俗解释与本篇场景</th><th>必须区分的概念</th></tr></thead><tbody><tr><td>Pint</td><td>Laravel 官方代码风格格式化工具</td><td>只管格式, 不管正确性</td></tr><tr><td>PHPStan / Larastan</td><td>PHP 静态分析工具, Larastan 提供 Laravel 感知</td><td>静态分析不能替代运行时测试</td></tr><tr><td>Pest / PHPUnit</td><td>PHP 测试框架</td><td>覆盖率数字不等于测试价值</td></tr><tr><td>Agent</td><td>能自主多步执行的 AI 程序</td><td>与&quot;单次生成&quot;的风险面不同</td></tr><tr><td>MCP Server</td><td>对外暴露工具的服务</td><td>开发期和生产期的权限应当不同</td></tr><tr><td>规则文件</td><td>仓库内给代理读的项目约定</td><td>是文档不是强制约束</td></tr><tr><td>Diff</td><td>两次版本之间的差异</td><td>审查的第一手依据</td></tr><tr><td>回归</td><td>改动引入的既有功能失效</td><td>AI 加速改动的同时会放大回归面</td></tr><tr><td>供应链</td><td>依赖、构建与发布链路的整体</td><td>一个新包就是一处新的信任关系</td></tr></tbody></table><h2 id="官方资料与核查口径" tabindex="-1">官方资料与核查口径 <a class="header-anchor" href="#官方资料与核查口径" aria-label="Permalink to &quot;官方资料与核查口径&quot;">​</a></h2><ul><li><a href="https://laravel.com/framework/docs/boost" target="_blank" rel="noreferrer">L1. AI 编码代理与上下文工程的通用实践</a>.</li><li><a href="https://laravel.com/framework/docs/boost" target="_blank" rel="noreferrer">L2. Laravel Boost 文档: MCP 工具集与 AI 指南</a>.</li><li><a href="https://laravel.com/docs/13.x" target="_blank" rel="noreferrer">L3. Laravel 官方文档: 测试、代码风格与依赖管理</a>.</li><li><a href="https://dora.dev/guides/dora-metrics-four-keys/" target="_blank" rel="noreferrer">L4. DORA 快速交付的四大关键指标</a>.</li><li><a href="https://www.php.net/supported-versions.php" target="_blank" rel="noreferrer">L5. PHP 支持版本与维护周期</a>.</li><li><a href="https://laravel.com/framework/docs/13.x/releases" target="_blank" rel="noreferrer">L6. Laravel Release Notes: 版本与支持政策</a>.</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./ai-production-engineering-interview.html">下一篇：AI 功能上线的工程化与安全合规（241—260）</a></li><li><a href="./php-ai-ecosystem-mcp-interview.html">上一篇：PHP AI 生态与 MCP 工具协议（201—220）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="https://laravel.com/framework/docs/boost" target="_blank" rel="noreferrer">Laravel Boost</a></li><li><a href="https://laravel.com/blog/announcing-laravel-boost" target="_blank" rel="noreferrer">Laravel Boost 官方博客</a></li></ul>',78)])])}const p=a(d,[["render",l]]);export{c as __pageData,p as default};
